#pragma once

#include <cstdint>
#include <span>
#include <string_view>
#include <vector>

// Where dmc3.exe's code starts each effect: every call of the spawn API
// (0x1402E7A90, 0x1402E7AB0, 0x1402E7CA0) and of the P/E/G/V factories,
// generated by tools/research/effect_spawn_sites.py. Addresses, class names,
// kinds and ids only. One row per (call, kind, id): a call that several
// branches reach with different ids has a row for each.
namespace dmcresource::effect_sites {

enum class SpawnCall : std::uint8_t {
    spawn = 0,         // 0x1402E7A90(kind, id, matrix, prep)
    spawn_flags = 1,   // 0x1402E7AB0(kind, id, matrix, prep, flags)
    spawn_raised = 2,  // 0x1402E7CA0(kind, id, matrix or none, flags): y + 2
    factory = 3,       // a kind's factory directly
};

struct SpawnSite final {
    std::uint64_t address{};   // the call
    std::uint64_t function{};  // the function making it
    // The class whose vtable methods surround that function (RTTI); the
    // nearest one when the function is not a method itself.
    const char* owner{};
    char kind{};               // 'P', 'E', 'G', 'V'; '?' when computed
    std::uint16_t id{};        // 0xFFFF when computed
    SpawnCall call{};
    std::int16_t mode{};       // prep mode (spawn) or flags; -1 when computed
};

[[nodiscard]] std::span<const SpawnSite> spawn_sites() noexcept;
// The classes whose code starts (kind, id), each once, in address order.
[[nodiscard]] std::vector<std::string_view> owners(char kind, std::uint16_t id);

}  // namespace dmcresource::effect_sites
